'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float32Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float32Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `toLocaleString` method', function test( t ) {
	var arr = new Float32Array( 2 );
	t.strictEqual( hasProp( arr, 'toLocaleString' ), true, 'has property' );
	t.strictEqual( isFunction( arr.toLocaleString ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.toLocaleString.call( value );
		};
	}
});

tape( 'the method returns an empty string if invoked on an empty array', function test( t ) {
	var str;
	var arr;

	arr = new Float32Array();
	str = arr.toLocaleString();

	t.strictEqual( str, '', 'returns expected value' );
	t.end();
});

tape( 'the method returns a locale string representation of a typed array', function test( t ) {
	var str;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	str = arr.toLocaleString();

	t.strictEqual( typeof str, 'string', 'returns a string' );
	t.end();
});
